package io.github.garemat.crumpet.gym

import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/** The in-session rules, against the brain's REAL /gym/state shape (the fixture is
 *  generated by crumpet core/gym.py — if the contract drifts, decoding it fails here). */
class SessionOpsTest {
    private val json = Json { ignoreUnknownKeys = true }
    private val state: GymState = json.decodeFromString(
        javaClass.classLoader!!.getResource("gym/state.json")!!.readText())
    private val chest = "chest press (machine)"

    private fun start(r: Routine = state.routines.first { it.id == "r1" }) =
        SessionOps.fromRoutine(r, state.exercises, "u1", "2026-10-26 07:30", 0)

    @Test
    fun `the brain's state decodes, tombstones and all`() {
        assertEquals(mapOf("r1" to false, "r2" to true), state.routines.associate { it.id to it.deleted })
        assertEquals("Old", state.routines.first { it.id == "r2" }.name)  // a tombstone keeps its name
        val info = state.exercises.getValue(chest)
        assertEquals("seat on 4", info.pref.note)
        assertEquals(60.0, info.bests.maxWeight!!, 0.0)
        assertTrue(state.exercises.getValue("pull up (assisted)").assisted)
        assertEquals("crumpet", state.card!!.body.single().target!!.reason)
    }

    @Test
    fun `prefill takes the engine target, warmups from last session`() {
        val sets = start().exercises.first { it.exercise == chest }.sets
        assertEquals(listOf("warmup", "working", "working"), sets.map { it.type })
        assertEquals(40.0, sets[0].weight)  // last session's warm-up
        val target = state.routines.first { it.id == "r1" }.body.first().target!!
        assertEquals(target.weight, sets[1].weight)
        assertEquals(target.reps, sets[1].reps)
    }

    @Test
    fun `crumpet's card weight is the prefill, and the card id isn't a routine id`() {
        val s = start(state.card!!)
        assertEquals(55.0, s.exercises.single().sets.first().weight)
        assertNull(s.routineId)
    }

    @Test
    fun `with no target the last session is the fallback`() {
        val re = RoutineExercise(chest, sets = listOf(RoutineSet(), RoutineSet()))
        val info = state.exercises.getValue(chest).copy(target = null)
        val sets = SessionOps.prefill(re, info)
        assertEquals(listOf(60.0 to 12, 60.0 to 12), sets.map { it.weight to it.reps })
    }

    @Test
    fun `ticking judges prs against history and compounds`() {
        var s = start()
        val ex = s.exercises.first { it.exercise == chest }
        val info = state.exercises.getValue(chest)
        s = SessionOps.editSet(s, ex.key, ex.sets[1].key, weight = 60.0, reps = 13)
        s = SessionOps.editSet(s, ex.key, ex.sets[2].key, weight = 60.0, reps = 13)
        s = SessionOps.toggleDone(s, ex.key, ex.sets[0].key, info)  // warm-up
        s = SessionOps.toggleDone(s, ex.key, ex.sets[1].key, info)
        s = SessionOps.toggleDone(s, ex.key, ex.sets[2].key, info)
        val sets = s.exercises.first { it.key == ex.key }.sets
        assertEquals(emptyList<String>(), sets[0].prs)           // warm-ups never PR
        assertTrue("reps" in sets[1].prs)                         // 13 > 12 at 60
        assertEquals(emptyList<String>(), sets[2].prs)           // equals the set before it
        s = SessionOps.toggleDone(s, ex.key, ex.sets[1].key, info) // untick → set 3 inherits the PR
        assertTrue("reps" in s.exercises.first { it.key == ex.key }.sets[2].prs)
    }

    @Test
    fun `a set needs reps to be ticked`() {
        var s = SessionOps.addExercise(SessionOps.empty("u", "W", "2026-10-26 07:00", 0), "new thing", null)
        val ex = s.exercises.single()
        assertNull(ex.sets.first().reps)
        s = SessionOps.toggleDone(s, ex.key, ex.sets.first().key, null)
        assertFalse(s.exercises.single().sets.first().done)
    }

    @Test
    fun `drop sets chain, round down to the step, and survive unticked parents on finish`() {
        var s = start()
        val ex = s.exercises.first { it.exercise == chest }
        s = SessionOps.addDrop(s, ex.key, 5.0)
        s = SessionOps.addDrop(s, ex.key, 5.0)
        var sets = s.exercises.first { it.key == ex.key }.sets
        assertEquals(listOf(null, null, null, 3, 4), sets.map { it.dropOf })
        val parentW = sets[2].weight!!
        assertEquals(SessionOps.roundDown(parentW * 0.75, 5.0), sets[3].weight)
        // fill + tick everything except the second working set (the drop's parent)
        for (set in sets) s = SessionOps.editSet(s, ex.key, set.key, reps = set.reps ?: 8)
        sets = s.exercises.first { it.key == ex.key }.sets
        for (i in listOf(0, 1, 3, 4)) s = SessionOps.toggleDone(s, ex.key, sets[i].key, null)
        val body = SessionOps.toBody(s, "2026-10-26 08:30")!!
        val sent = body.exercises.first { it.exercise == chest }.sets
        assertEquals(listOf("warmup", "working", "drop", "drop"), sent.map { it.type })
        assertEquals(listOf(null, null, 2, 3), sent.map { it.dropOf })  // re-pointed to SENT numbering
        assertTrue(sent.all { it.dropOf == null || it.dropOf!! < sent.indexOf(it) + 1 })
    }

    @Test
    fun `a drop with no ticked parent goes as a working set`() {
        var s = start()
        val ex = s.exercises.first { it.exercise == chest }
        s = SessionOps.addDrop(s, ex.key, 5.0)
        val drop = s.exercises.first { it.key == ex.key }.sets.last()
        s = SessionOps.editSet(s, ex.key, drop.key, reps = 10)
        s = SessionOps.toggleDone(s, ex.key, drop.key, null)
        val sent = SessionOps.toBody(s, "x")!!.exercises.single().sets
        assertEquals(listOf("working" to null), sent.map { it.type to it.dropOf })
    }

    @Test
    fun `removing a set re-points the drop chain`() {
        var s = start()
        val ex = s.exercises.first { it.exercise == chest }
        s = SessionOps.addDrop(s, ex.key, 5.0)        // drop of set 3
        val third = s.exercises.first { it.key == ex.key }.sets[2]
        s = SessionOps.removeSet(s, ex.key, third.key)
        assertEquals(2, s.exercises.first { it.key == ex.key }.sets.last().dropOf)
        val first = s.exercises.first { it.key == ex.key }.sets[0]
        val second = s.exercises.first { it.key == ex.key }.sets[1]
        s = SessionOps.removeSet(s, ex.key, second.key)
        s = SessionOps.removeSet(s, ex.key, first.key)
        val last = s.exercises.first { it.key == ex.key }.sets.single()
        assertEquals("working" to null, last.type to last.dropOf)  // nothing left to drop from
    }

    @Test
    fun `nothing ticked means nothing to send`() {
        assertNull(SessionOps.toBody(start(), "x"))
    }

    @Test
    fun `finishing folds into the cache and makes stale targets fall back`() {
        var s = start()
        val ex = s.exercises.first { it.exercise == chest }
        s = SessionOps.editSet(s, ex.key, ex.sets[1].key, weight = 65.0, reps = 9)
        s = SessionOps.toggleDone(s, ex.key, ex.sets[1].key, null)
        val folded = SessionOps.foldIntoState(state, SessionOps.toBody(s, "2026-10-26 08:00")!!)
        val info = folded.exercises.getValue(chest)
        assertEquals("2026-10-26", info.last!!.day)
        assertEquals(65.0, info.bests.maxWeight!!, 0.0)
        assertNull(info.target)
        assertNull(folded.routines.first { it.id == "r1" }.body.first().target)
        // and the next session pre-fills from what was just done
        val next = SessionOps.fromRoutine(folded.routines.first { it.id == "r1" }, folded.exercises, "u2", "x", 0)
        assertEquals(65.0, next.exercises.first { it.exercise == chest }.sets[1].weight)
    }

    @Test
    fun `superset and rest come through from the routine and prefs`() {
        val s = start()
        assertEquals("A", s.exercises.first { it.exercise == "triceps dip" }.superset)
        assertEquals(120, s.exercises.first { it.exercise == chest }.restS)
    }
}

class WireContractTest {
    /** The exact bytes the outbox POSTs — pinned so a model rename can't silently change
     *  the wire. This literal is also fed to the brain's ingest (crumpet core/gym.py) when
     *  the contract changes; keep the two in step. */
    @Test
    fun `session body encodes to the brain's field names`() {
        val body = SessionBody("u-1", "r1", "Push", "2026-10-26 07:30", "2026-10-26 08:20", "felt good",
            listOf(SessionExerciseBody("chest press (machine)", "A", "seat on 4", listOf(
                SessionSetBody("warmup", 15, 40.0), SessionSetBody("working", 10, 60.0),
                SessionSetBody("drop", 8, 45.0, 2))),
                SessionExerciseBody("triceps dip", null, "", listOf(SessionSetBody("working", 6)))))
        val encoded = Json { encodeDefaults = true }.encodeToString(SessionBody.serializer(), body)
        assertEquals(EXPECTED, encoded)
    }

    companion object {
        const val EXPECTED = """{"uid":"u-1","routine_id":"r1","title":"Push","started_at":"2026-10-26 07:30","ended_at":"2026-10-26 08:20","note":"felt good","exercises":[{"exercise":"chest press (machine)","superset":"A","note":"seat on 4","sets":[{"type":"warmup","reps":15,"weight":40.0,"drop_of":null},{"type":"working","reps":10,"weight":60.0,"drop_of":null},{"type":"drop","reps":8,"weight":45.0,"drop_of":2}]},{"exercise":"triceps dip","superset":null,"note":"","sets":[{"type":"working","reps":6,"weight":null,"drop_of":null}]}]}"""
    }
}
